import unittest
from telemetry import DELETE, merge_layers

class MergeLayersTests(unittest.TestCase):
    def test_nested_overlay_preserves_siblings_and_deletes_leaf(self):
        base = {"exporter": {"endpoint": "https://collector.internal", "headers": {"tenant": "north", "legacy": "remove-me"}, "retries": 3}, "enabled": True}
        overlay = {"exporter": {"headers": {"legacy": DELETE, "trace": "on"}, "retries": 5}}
        self.assertEqual(merge_layers(base, overlay), {"exporter": {"endpoint": "https://collector.internal", "headers": {"tenant": "north", "trace": "on"}, "retries": 5}, "enabled": True})

    def test_inputs_are_not_mutated(self):
        base = {"labels": {"service": "api"}}
        overlay = {"labels": {"region": "eu"}}
        merge_layers(base, overlay)
        self.assertEqual(base, {"labels": {"service": "api"}})
        self.assertEqual(overlay, {"labels": {"region": "eu"}})

if __name__ == "__main__":
    unittest.main()

"""Private behavioral checks for telemetry.merge (stdlib only)."""
from __future__ import annotations
import importlib.util
import sys
from collections import OrderedDict
from pathlib import Path

def load_candidate(path: str):
    candidate = Path(path)
    assert candidate.is_file()
    spec = importlib.util.spec_from_file_location("candidate_merge", candidate)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

def main() -> None:
    assert len(sys.argv) == 2
    module = load_candidate(sys.argv[1])
    merge, delete = module.merge_layers, module.DELETE
    base = {"exporter": {"endpoint": "https://collector.internal", "headers": {"tenant": "north", "legacy": "remove-me"}, "retries": 3}, "enabled": True}
    overlay = {"exporter": {"headers": {"legacy": delete, "trace": "on"}, "retries": 5}}
    assert merge(base, overlay) == {"exporter": {"endpoint": "https://collector.internal", "headers": {"tenant": "north", "trace": "on"}, "retries": 5}, "enabled": True}
    assert merge({"obsolete": 1, "tree": {"a": 1, "b": 2}}, {"obsolete": delete, "missing": delete, "tree": {"a": 7}}, {"tree": {"b": delete, "c": 9}}) == {"tree": {"a": 7, "c": 9}}
    assert merge({"mode": "simple", "old": {"x": 1}}, {"mode": {"x": 2}, "old": 4}) == {"mode": {"x": 2}, "old": 4}
    assert merge({"x": {"a": 1}}, OrderedDict([("x", OrderedDict([("b", 2)]))])) == {"x": {"a": 1, "b": 2}}
    base_mutable = {"nested": {"items": [1], "keep": {"v": 3}}}
    overlay_mutable = {"nested": {"items": [2], "added": {"v": 4}}}
    result = merge(base_mutable, overlay_mutable)
    result["nested"]["items"].append(99)
    result["nested"]["keep"]["v"] = 30
    result["nested"]["added"]["v"] = 40
    assert base_mutable == {"nested": {"items": [1], "keep": {"v": 3}}}
    assert overlay_mutable == {"nested": {"items": [2], "added": {"v": 4}}}
    assert merge({}) == {}
    source = {"a": {"b": []}}
    cloned = merge(source)
    assert cloned == source and cloned is not source and cloned["a"] is not source["a"]

if __name__ == "__main__":
    main()
